import { IngestPipeline } from "@514labs/moose-lib";

// Event data model matching the target schema
export interface Event {
  event_id: string;
  event_ts: Date; // DateTime
  user_id: string;
  event_type: string;
  value: number; // Float64, nulls will become 0
}

// Create an ingest pipeline for events
export const EventPipeline = new IngestPipeline<Event>("Event", {
  table: {
    orderByFields: ["event_ts", "user_id", "event_type"] // Order by timestamp first for time-series queries
  },
  stream: true,
  ingestApi: true,
});

