import * as fs from 'fs';
import * as path from 'path';
import axios from 'axios';

interface Event {
  event_id: string;
  event_ts: string; // Will send as ISO string
  user_id: string;
  event_type: string;
  value: number;
}

// Function to parse different date formats
function parseDate(dateStr: string): string {
  // Handle DD/MM/YYYY format (like 15/01/2026)
  if (dateStr.includes('/')) {
    const [day, month, year] = dateStr.split('/');
    return new Date(`${year}-${month}-${day}T12:00:00Z`).toISOString();
  }

  // Handle ISO format (like 2026-01-15T10:00:00Z)
  if (dateStr.includes('T')) {
    return new Date(dateStr).toISOString();
  }

  // Fallback
  return new Date(dateStr).toISOString();
}

// Function to parse value field, converting nulls to 0
function parseValue(valueStr: string): number {
  if (!valueStr || valueStr.trim() === '' ||
      valueStr.toLowerCase() === 'null' ||
      valueStr.toLowerCase() === 'n/a') {
    return 0;
  }
  return parseFloat(valueStr) || 0;
}

// Function to clean and parse CSV content
function parseCSV(content: string, filename: string): Event[] {
  const lines = content.trim().split('\n');
  const events: Event[] = [];

  let headerFound = false;

  for (const line of lines) {
    // Remove trailing commas and trim whitespace
    const cleanedLine = line.replace(/,+$/, '').trim();

    if (!cleanedLine) continue;

    // Skip header rows (including duplicates)
    if (cleanedLine.includes('event_id,event_ts,user_id,event_type,value')) {
      headerFound = true;
      continue;
    }

    if (!headerFound) continue;

    const [event_id, event_ts, user_id, event_type, value] = cleanedLine.split(',');

    if (!event_id || !event_ts || !user_id || !event_type) {
      console.log(`Skipping invalid line in ${filename}: ${cleanedLine}`);
      continue;
    }

    try {
      const event: Event = {
        event_id: event_id.trim(),
        event_ts: parseDate(event_ts.trim()),
        user_id: user_id.trim(),
        event_type: event_type.trim(),
        value: parseValue(value?.trim() || '')
      };

      events.push(event);
    } catch (error) {
      console.log(`Error parsing line in ${filename}: ${cleanedLine}`, error);
    }
  }

  return events;
}

// Main function to load all CSV files
async function loadCSVData() {
  const csvDir = '/data/csv';
  const ingestUrl = 'http://localhost:4000/ingest/Event';

  console.log('Starting CSV data loading...');

  const csvFiles = fs.readdirSync(csvDir).filter(file => file.endsWith('.csv'));
  console.log(`Found ${csvFiles.length} CSV files: ${csvFiles.join(', ')}`);

  let totalEvents = 0;

  for (const file of csvFiles) {
    const filePath = path.join(csvDir, file);
    const content = fs.readFileSync(filePath, 'utf-8');

    console.log(`\nProcessing ${file}...`);
    const events = parseCSV(content, file);
    console.log(`Parsed ${events.length} events from ${file}`);

    // Send events to Moose ingest API
    for (const event of events) {
      try {
        await axios.post(ingestUrl, event, {
          headers: {
            'Content-Type': 'application/json'
          }
        });
        console.log(`✓ Loaded event: ${event.event_id}`);
        totalEvents++;
      } catch (error: any) {
        console.error(`✗ Failed to load event ${event.event_id}:`, error.response?.data || error.message);
      }
    }
  }

  console.log(`\n🎉 Successfully loaded ${totalEvents} events total!`);
  return totalEvents;
}

// Run the script if called directly
if (require.main === module) {
  loadCSVData().then((count) => {
    console.log(`Process completed. ${count} events loaded.`);
    process.exit(0);
  }).catch((error) => {
    console.error('Process failed:', error);
    process.exit(1);
  });
}

export { loadCSVData };

